def build(h):
    route = h['route']
    scale = h['yards'] / sum(math.dist(a,b) for a,b in zip(route,route[1:]))
    tx, ty = route[0]
    # Keep the artwork level. Aim headings already use the actual pin/ball vector.
    def world(p): return [round((p[1]-ty)*scale,6), round((p[0]-tx)*scale,6)]
    def poly(points, holes=()): return dict(outer=list(map(world,points)),holes=[list(map(world,r)) for r in holes])
    edge = [[0,0],[1774,0],[1774,887],[0,887]]
    surfaces = {k:[poly(h[k])] for k in ('fairway','green','tee')}
    surfaces.update({k:[poly(p) for p in h[k]] for k in ('sand','water')})
    surfaces['nature']=[poly(edge,[h['clearing']])]
    course = dict(id=h['id'],name=h['name'],par=h['par'],yards=h['yards'],description=h['description'],
        tee=world(route[0]),pin=world(route[-1]),playing_line=list(map(world,route)),
        bounds=[-ty*scale,(887-ty)*scale,-tx*scale,(1774-tx)*scale],boundary=poly(edge),surfaces=surfaces,
        image=dict(href='/assets/art/'+h['id']+'.png',width=1774,height=887,
                   transform=[scale,0,0,scale,-tx*scale,-ty*scale]),
        provenance=dict(kind='original_generated',created='2026-10-02',
            description='Original AI artwork with reviewed hand-traced fictional game surfaces.',
            geometry_review='fictional_pixel_trace_v1',route_yards=h['yards'],
            straight_yards=round(math.dist(route[0],route[-1])*scale,1),
            pixel_route=route,pixels_to_yards=scale,
            attribution='TraceLoft original fictional hole · AI artwork · flat-green game'),
        warnings=['Fictional hole: hand-traced surface edges are approximate game boundaries, not surveyed terrain.',
                  'Listed yardage follows the playing route; ball-to-pin and aim distances are straight-line yards.',
                  'Flat greens, no elevation or tree collisions. Water/OB add one penalty and replay the previous position.'])
    left,right,near,far=course['bounds']
    course['viewbox']=[near,left,far-near,right-left]
    validate_edits({k:course[k] for k in ('surfaces','boundary','tee','pin')})
    assert classify(course['tee'],course)=='tee'
    assert classify(course['pin'],course)=='green'
    for lie,p in h['samples'].items(): assert classify(world(p),course)==lie,(h['id'],lie,p)
    return course


if __name__=='__main__':
    for hole in HOLES:
        course=build(hole)
        (ROOT/'courses'/f"{hole['id']}.json").write_text(json.dumps(course,indent=2)+'\n',encoding='utf-8')
        print(hole['name'],course['provenance']['route_yards'],'route yd;',course['provenance']['straight_yards'],'straight yd')
